static void load(const char *objpath) {
 struct statfs fs; if(statfs("/sys/fs/bpf",&fs) || fs.f_type!=BPF_FS_MAGIC) { errno=EINVAL; die("bpffs must be mounted"); }
 if(mkdir(PIN,0700)) die("create new pin directory (refuses existing)");
 struct bpf_object *obj=bpf_object__open_file(objpath,NULL);
 if(libbpf_get_error(obj)) { errno=(int)-libbpf_get_error(obj); rmdir(PIN); die("open BPF object"); }
 struct bpf_link *attached[4]={0}; char p[256]; int err=0;
 if(bpf_object__load(obj)) { err=errno; goto fail; }
 for(unsigned int i=0;i<4;i++) {
  struct bpf_map *m=bpf_object__find_map_by_name(obj,maps[i]);
  if(!m) { err=ENOENT; goto fail; } path(p,maps[i]);
  if(bpf_map__pin(m,p) || chmod(p,0600)) { err=errno; goto fail; }
 }
 /* Attach both while zero initialized config means OFF. */
 for(unsigned int i=0;i<4;i++) {
  struct bpf_program *prog=bpf_object__find_program_by_name(obj,programs[i]);
  if(!prog) { err=ENOENT; goto fail; }
  attached[i]=bpf_program__attach_lsm(prog);
  if(libbpf_get_error(attached[i])) { err=(int)-libbpf_get_error(attached[i]); attached[i]=NULL; goto fail; }
  path(p,links[i]); if(bpf_link__pin(attached[i],p) || chmod(p,0600)) { err=errno; goto fail; }
 }
 struct stat s; if(stat("/dev/btrfs-control",&s) || !S_ISCHR(s.st_mode)) { err=ENODEV; goto fail; }
 struct guard_config cfg={GUARD_OFF,(major(s.st_rdev)<<20)|minor(s.st_rdev)};
 set_cfg(cfg);
 for(unsigned int i=0;i<4;i++) bpf_link__destroy(attached[i]);
 bpf_object__close(obj); puts("loaded native+compat+rmdir+rename links; mode=OFF"); return;
fail:
 for(unsigned int i=0;i<4;i++) { path(p,links[i]); unlink(p); if(attached[i]) bpf_link__destroy(attached[i]); }
 for(unsigned int i=0;i<4;i++) { path(p,maps[i]); unlink(p); }
 bpf_object__close(obj); rmdir(PIN); errno=err?err:EIO; die("load failed; nothing armed");
}
