[ -x "$THREETCHED_BIN" ] || { echo "pinned threetched binary is missing" >&2; exit 78; }
[ -f "$THREETCHED_MANIFEST" ] || { echo "threetched provenance manifest is missing" >&2; exit 78; }
manifest_format=$(jq -er '.format' "$THREETCHED_MANIFEST")
manifest_tag=$(jq -er '.upstream.tag | select(test("^v[0-9]+[.][0-9]+[.][0-9]+([-+][A-Za-z0-9.-]+)?$"))' "$THREETCHED_MANIFEST")
manifest_binary_sha256=$(jq -er '.artifact.sha256' "$THREETCHED_MANIFEST")
if [ "$manifest_format" = "opdbus.threetched.v2" ]; then
    jq -e '.artifact.name == "threetched" and
        .artifact.upstream_binary == "zeroclaw" and
        (.upstream.commit | test("^[0-9a-f]{40}$"))' "$THREETCHED_MANIFEST" >/dev/null || {
        echo "invalid threetched artifact provenance" >&2; exit 78;
    }
    [ "$(sha256sum "$THREETCHED_BIN" | awk '{print $1}')" = "$manifest_binary_sha256" ] || { echo "tched_router binary/provenance mismatch" >&2; exit 78; }
    [ "$("$THREETCHED_BIN" --version)" = "zeroclaw ${manifest_tag#v}" ] || { echo "unexpected threetched version" >&2; exit 78; }
elif [ "$manifest_format" = "opdbus.threetched.v1" ]; then
    jq -e '.artifact.name == "threetched" and
        (.upstream.commit | test("^[0-9a-f]{40}$")) and
        (.patches.branding_sha256 | test("^[0-9a-f]{64}$"))' "$THREETCHED_MANIFEST" >/dev/null || {
        echo "invalid threetched artifact provenance" >&2; exit 78;
    }
    [ "$(sha256sum "$THREETCHED_BIN" | awk '{print $1}')" = "$manifest_binary_sha256" ] || { echo "tched_router binary/provenance mismatch" >&2; exit 78; }
    [ "$("$THREETCHED_BIN" --version)" = "threetched ${manifest_tag#v}" ] || { echo "unexpected threetched version" >&2; exit 78; }
else
    echo "unsupported tched_router provenance: $manifest_format" >&2
    exit 78
fi

